param(
    [Parameter(Mandatory = $true)]
    [string]$Version
)

$ErrorActionPreference = 'Stop'

$parts = $Version.Split('.')
if ($parts.Count -ne 4) {
    throw "Version must use yyyy.MM.dd.buildnumber, got '$Version'."
}

$numbers = @()
foreach ($part in $parts) {
    $value = 0
    if (-not [int]::TryParse($part, [ref]$value) -or $value -lt 0 -or $value -gt 65535) {
        throw "Invalid version component '$part' in '$Version'."
    }
    $numbers += $value
}

$content = @"
#pragma once

// Generated by tools/set-version.ps1. Do not edit by hand in CI builds.
#define USBINFO_VERSION_MAJOR $($numbers[0])
#define USBINFO_VERSION_MINOR $($numbers[1])
#define USBINFO_VERSION_PATCH $($numbers[2])
#define USBINFO_VERSION_BUILD $($numbers[3])
#define USBINFO_VERSION_STRING "$Version"
#define USBINFO_VERSION_WSTRING L"$Version"
"@ + "`r`n"

$target = Join-Path $PSScriptRoot '..\src\Version.h'
$fullPath = [System.IO.Path]::GetFullPath($target)
[System.IO.File]::WriteAllText($fullPath, $content, (New-Object System.Text.UTF8Encoding($false)))
Write-Host "USBInfo version set to $Version"
